-- Explicit sample content only; operational rules, fees, and qualifications remain unchanged.
-- Refuses to overwrite existing rules. All writes use the audited owner-only publishing RPCs.
begin;
do $$
declare producer uuid; owner_id uuid; revision integer;
begin
  select id into strict producer from public.producers where slug='ultimate-calf-roping';
  select id into strict owner_id from auth.users where lower(email)='psides83@hotmail.com';
  if exists(select 1 from public.producer_rules where producer_id=producer) then
    raise exception 'Rules already exist; review before replacing them';
  end if;
  if exists(select 1 from public.producer_bulletins where producer_id=producer and id in ('91000000-0000-4000-8000-000000000001'::uuid,'91000000-0000-4000-8000-000000000002'::uuid,'91000000-0000-4000-8000-000000000003'::uuid)) then
    raise exception 'Sample bulletins already exist';
  end if;
  perform set_config('request.jwt.claim.sub',owner_id::text,true);
  execute 'set local role authenticated';
  revision:=public.save_producer_rules(producer,0,'{"title":"Rules & Information — Sample","introduction":"**Sample content for testing only.** These condensed examples are not an authoritative rulebook. [Source: UCR Rules & Information](https://www.ucroping.com/rules-info). Review the original page before relying on any policy.","effectiveOn":"","sections":[{"id":"90000000-0000-4000-8000-000000000001","title":"Membership and conduct","content":"Membership costs $100; $50 supports finals added money. Installments are available. Livestock abuse and inappropriate conduct carry disciplinary consequences.","subsections":[]},{"id":"90000000-0000-4000-8000-000000000002","title":"Arena competition","content":"Tie-down requires a legal three-leg tie. Cattle run through the chute. Judges determine reruns, barrier decisions, and safety interventions.","subsections":[{"id":"90000000-0000-4000-8000-000000000003","title":"Time limits","content":"Standard limit: 30 seconds; #15, #13 and #12: 60 seconds."}]},{"id":"90000000-0000-4000-8000-000000000004","title":"Classifications","content":"Classification considers ability, not time alone.","subsections":[{"id":"90000000-0000-4000-8000-000000000005","title":"Handicap Breakaway","content":"Adjustments: Open +0.25, A 0.00, B −0.25, C −0.50 seconds."},{"id":"90000000-0000-4000-8000-000000000006","title":"4-D Breakaway","content":"Half-second bands; eligibility and paid places depend on producer rules."}]},{"id":"90000000-0000-4000-8000-000000000007","title":"Classification review","content":"Fast runs trigger review. Moves affect standings carryover; producer discretion remains important.","subsections":[]},{"id":"90000000-0000-4000-8000-000000000008","title":"Finals eligibility","content":"Minimum attendance applies. Preliminary and Top 25 competitions can count; finals cannot. Selected qualifying events award extra positions.","subsections":[]}],"attachments":[]}'::jsonb,'publish');
  revision:=public.save_producer_bulletins(producer,'91000000-0000-4000-8000-000000000001',0,'{"title":"2026–2027 production charges — Sample","introduction":"**Sample content for testing only.** These condensed examples are not an authoritative rulebook. [Source: UCR Rules & Information](https://www.ucroping.com/rules-info). Review the original page before relying on any policy. Bulletin dates indicate when this sample was imported, not the original announcement date.","effectiveOn":"2026-10-08","sections":[{"id":"90000000-0000-4000-8000-000000000020","title":"Season fees","content":"Production charge: $35 per run, including $25 for stock.","subsections":[]}],"attachments":[]}'::jsonb,'publish');
  revision:=public.save_producer_bulletins(producer,'91000000-0000-4000-8000-000000000002',0,'{"title":"Top 25 Breakaway added for 2026–2027 — Sample","introduction":"**Sample content for testing only.** These condensed examples are not an authoritative rulebook. [Source: UCR Rules & Information](https://www.ucroping.com/rules-info). Review the original page before relying on any policy. Bulletin dates indicate when this sample was imported, not the original announcement date.","effectiveOn":"2026-10-08","sections":[{"id":"90000000-0000-4000-8000-000000000021","title":"Season update","content":"Breakaway joins the Top 25 program this season.","subsections":[]}],"attachments":[]}'::jsonb,'publish');
  revision:=public.save_producer_bulletins(producer,'91000000-0000-4000-8000-000000000003',0,'{"title":"Cowtown: January 4–5, 2027 — Sample","introduction":"**Sample content for testing only.** These condensed examples are not an authoritative rulebook. [Source: UCR Rules & Information](https://www.ucroping.com/rules-info). Review the original page before relying on any policy. Bulletin dates indicate when this sample was imported, not the original announcement date.","effectiveOn":"2026-10-08","sections":[{"id":"90000000-0000-4000-8000-000000000022","title":"Special event","content":"Top 20 by class; November 2 standings cutoff. Attendance requirements apply. Four-head format; $1,500 entry.","subsections":[]}],"attachments":[]}'::jsonb,'publish');
  execute 'reset role';
